'use client';

/**
 * The board bench — a dev-only harness that plays a golden plan so the hand can be looked at,
 * screenshotted and regression-tested without the brain, the network or a lesson.
 *
 * Two things live here:
 *
 *  1. **The Pythagoras plan**, written in TypeScript, computed in code and marked verified — the
 *     original hand-built golden, kept because it is the readable example of what a plan IS.
 *  2. **The golden gallery**: the twelve boards in `goldens/`, generated by `goldens/build.ts` and
 *     shared byte-for-byte with the brain's own golden test. The gallery is what the Playwright
 *     suite drives, and what a latency measurement is taken from.
 *
 * Reachable only in dev, three ways:
 *   · `/board-bench.html#<name>` — the hermetic page the e2e suite uses (no app, no router, no bus);
 *   · mount `<BoardBenchGate />` anywhere near the root — it shows itself at `#board-bench`;
 *   · or call `window.__woboBoardBench()` from the console.
 *
 * Everything a test needs is on `window.__woboBench` (see `BenchApi`): the names, a play call, the
 * time to the first stroke, and a ledger of what actually landed on the board.
 */

import {
  type BoardEvent,
  BoardStore,
  boardBook,
  parseBoardPlan,
  plane,
  WoboFullBoard,
  WoboPlane,
} from '@wobo/wobo';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { GOLDEN_BOARDS, type GoldenBoard, goldenBoard } from './goldens';
import { GOLDEN_BRAINS } from './goldens/brains';
import { changeVariable } from './variables';

// --- The hand-written golden -------------------------------------------------------------------------

/** The triangle, in board units. A 3-4-5 at forty units to the side. */
const UNIT = 40;
const A = 4 * UNIT; // the horizontal leg
const B = 3 * UNIT; // the vertical leg
const ORIGIN: [number, number] = [250, 400];

/** Computed here, in code, and only then drawn — never a number the model wrote. */
function pythagoras(a: number, b: number) {
  const aSq = a * a;
  const bSq = b * b;
  const cSq = aSq + bSq;
  const c = Math.sqrt(cSq);
  return { a, b, c, aSq, bSq, cSq, verified: Math.abs(aSq + bSq - cSq) < 1e-9 };
}

const T = pythagoras(4, 3);
const C = T.c * UNIT;

/**
 * The outward unit normal of the hypotenuse, so the big square is built away from the triangle
 * rather than on top of it.
 */
const hypNormal: [number, number] = [B / C, -A / C];

const ink = (object: unknown, t: number): BoardEvent => ({ type: 'ink', object, t }) as BoardEvent;

